"""Insula Neuro Score — Phase 6 library expansion.
Each score below was verified against the sources cited in its `sources` field before implementation
(see docs/PHASE-6.md for the verification log). Descriptors are paraphrased in original wording."""

REVIEWED = "2026-10-02"
REVIEW = "Drafted from verified sources; pending independent clinician review before clinical release."
CV = "6.0.0"

def o(value, label, points, code=None, detail=None, exclusive=False):
    d = {"value": str(value), "label": label, "points": points}
    if code is not None: d["code"] = code
    if detail: d["detail"] = detail
    if exclusive: d["exclusive"] = True
    return d
def single(id, label, short, options, help=None, nt=None):
    d = {"id": id, "type": "single", "label": label, "short": short, "options": options}
    if help: d["help"] = help
    if nt: d["notTestable"] = nt
    return d
def yn(id, label, short, yes="Present", no="Absent", help=None, points=1):
    return single(id, label, short, [o("no", no, 0), o("yes", yes, points)], help)
def st(id, tone, label, summary, rng=None, detail=None, mn=None, mx=None):
    d = {"id": id, "tone": tone, "label": label, "summary": summary}
    if rng: d["range"] = rng
    if detail: d["detail"] = detail
    if mn is not None: d["min"] = mn; d["max"] = mx
    return d
def comp_each(inputs):  # one component per input
    return [{"id": "c_" + i["id"], "label": i["label"], "inputs": [i["id"]]} for i in inputs]
def conf(*pairs): return [{"factor": f, "effect": e} for f, e in pairs]
def score(**k):
    d = {"contentVersion": CV, "lastReviewed": REVIEWED, "reviewStatus": REVIEW, "aliases": [], "scoringRules": [], "consistencyRules": [],
         "commonErrors": [], "relatedScores": []}
    d.update(k)
    if "components" not in d: d["components"] = comp_each(d["inputDefinitions"])
    return d
def band_rules(bands):  # [(maxInclusive, stateId)] ... last (None, id)
    return [{"when": "total <= %s" % m, "state": s} if m is not None else {"state": s} for m, s in bands]

GCS_SRC = {"citation": "Teasdale G, Jennett B. Assessment of coma and impaired consciousness. A practical scale. Lancet. 1974;2(7872):81-84."}

