    pc = [o("lt", "Left thalamus", 1), o("rt", "Right thalamus", 1), o("lc", "Left cerebellar hemisphere", 1), o("rc", "Right cerebellar hemisphere", 1),
          o("lp", "Left PCA territory", 1), o("rp", "Right PCA territory", 1), o("mb", "Midbrain (any part)", 2, detail="2 points regardless of extent."), o("po", "Pons (any part)", 2, detail="2 points regardless of extent.")]
